<?php
namespace Tests\Feature;
use App\Models\{User,Owner,Venue,Booking,BookingPayment,MailNotification};use App\Services\{VenueSettings,BookingEngine};use App\Services\Realtime\Invalidations;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\{DB,Broadcast};use Illuminate\Foundation\Http\Middleware\ValidateCsrfToken;use Tests\Support\StrictCsrf;use Tests\TestCase;use Illuminate\Support\Str;
class RealtimeTest extends TestCase {
 use RefreshDatabase;
 protected function setUp():void {parent::setUp();config(['realtime.enabled'=>true,'realtime.key'=>'test-key','broadcasting.connections.reverb.key'=>'test-key','broadcasting.connections.reverb.secret'=>'test-secret','broadcasting.connections.reverb.app_id'=>'test-app']);}
 private function venue(bool $published=true):Venue{$u=User::factory()->create();$o=Owner::unguarded(fn()=>Owner::create(['user_id'=>$u->id,'email'=>$u->email,'name'=>'Dueño','password'=>'OwnerPassword12345','activated'=>true,'email_verified_at'=>now()]));return Venue::create(['owner_id'=>$u->id,'owner_account_id'=>$o->id,'name'=>'Local privado prueba','slug'=>'ws-'.Str::lower(Str::random(8)),'published'=>$published,'settings'=>array_replace(VenueSettings::defaults(),['capacity'=>100,'open_hour'=>10,'close_hour'=>26,'prep_minutes'=>0,'clean_minutes'=>60,'included_hours'=>8,'weekday_price'=>500000,'weekend_price'=>700000,'holiday_price'=>900000,'extra_hour_price'=>100000,'deposit_value'=>30,'address'=>'Colima','lat'=>19.2,'lng'=>-103.7])]);}
 private function booking(Venue $v,?User $u=null):Booking{return app(BookingEngine::class)->reserve($v,($u??User::factory()->create())->id,['date'=>now()->addMonth()->format('Y-m-d'),'start'=>12,'hours'=>8,'guests'=>10]);}
 public function test_owner_can_authorize_only_their_private_channel():void{$v=$this->venue();$this->actingAs($v->owner)->postJson('/api/realtime/auth',['socket_id'=>'123.456','channel_name'=>'private-owner.'.$v->owner_account_id])->assertOk()->assertJsonPath('auth','test-key:'.hash_hmac('sha256','123.456:private-owner.'.$v->owner_account_id,'test-secret'));$this->postJson('/api/realtime/auth',['socket_id'=>'123.456','channel_name'=>'private-owner.999'])->assertForbidden();$this->postJson('/api/realtime/auth',['socket_id'=>'123.456','channel_name'=>'private-customer.'.$v->owner_id])->assertForbidden();}
 public function test_customer_cannot_join_owner_or_other_customer_channels():void{$u=User::factory()->create();$this->actingAs($u)->postJson('/api/realtime/auth',['socket_id'=>'123.456','channel_name'=>'private-customer.'.$u->id])->assertOk();$this->postJson('/api/realtime/auth',['socket_id'=>'123.456','channel_name'=>'private-owner.'.$u->id])->assertForbidden();$this->postJson('/api/realtime/auth',['socket_id'=>'123.456','channel_name'=>'private-customer.999'])->assertForbidden();}
 public function test_guest_and_invalid_channel_are_denied():void{$this->postJson('/api/realtime/auth',['socket_id'=>'123.456','channel_name'=>'private-owner.1'])->assertForbidden();$this->postJson('/api/realtime/auth',['socket_id'=>'bad','channel_name'=>'presence-anything'])->assertUnprocessable();}
 public function test_channel_authorization_requires_real_csrf_validation():void{$this->app->bind(ValidateCsrfToken::class,fn($app)=>new StrictCsrf($app,$app['encrypter']));$this->actingAs(User::factory()->create())->postJson('/api/realtime/auth',['socket_id'=>'123.456','channel_name'=>'private-customer.1'])->assertStatus(419);}
 public function test_me_exposes_public_key_but_never_secret():void{$this->getJson('/api/me')->assertJsonPath('realtime.enabled',true)->assertJsonPath('realtime.key','test-key')->assertDontSee('test-secret');}
 public function test_published_edits_enqueue_public_and_scoped_private_invalidations():void{$v=$this->venue();DB::table('realtime_outbox')->delete();$s=$v->settings;$s['weekday_price']+=100;$v->update(['settings'=>$s]);$row=DB::table('realtime_outbox')->first();$channels=json_decode($row->channels,true);$this->assertContains('catalogue',$channels);$this->assertContains('venue.'.$v->id,$channels);$this->assertContains('private-owner.'.$v->owner_account_id,$channels);$this->assertStringNotContainsString('Local privado',$row->channels);}
 public function test_drafts_never_emit_public_events():void{$v=$this->venue(false);$channels=json_decode(DB::table('realtime_outbox')->first()->channels,true);$this->assertSame(['private-owner.'.$v->owner_account_id],$channels);}
 public function test_unpublishing_still_invalidates_previously_public_page():void{$v=$this->venue();DB::table('realtime_outbox')->delete();$v->update(['published'=>false]);$this->assertContains('venue.'.$v->id,json_decode(DB::table('realtime_outbox')->first()->channels,true));}
 public function test_public_booking_events_contain_no_customer_information():void{$v=$this->venue();DB::table('realtime_outbox')->delete();$u=User::factory()->create();$b=$this->booking($v,$u);$row=DB::table('realtime_outbox')->first();$channels=json_decode($row->channels,true);$this->assertContains('venue.'.$v->id,$channels);$this->assertContains('private-customer.'.$u->id,$channels);$this->assertSame('booking',$row->kind);$this->assertStringNotContainsString($u->email,json_encode($row));$this->assertStringNotContainsString($b->id,json_encode($row));}
 public function test_transaction_rollback_discards_its_invalidations():void{$v=$this->venue();DB::table('realtime_outbox')->delete();try{DB::transaction(function()use($v){$v->update(['name'=>'Cambio que se revierte']);throw new \RuntimeException('Rollback de prueba');});}catch(\RuntimeException $e){}$this->assertSame(0,DB::table('realtime_outbox')->count());$this->assertNotSame('Cambio que se revierte',$v->fresh()->name);}
 public function test_expired_holds_emit_once_without_changing_booking_status():void{$v=$this->venue();$b=$this->booking($v);$b->update(['expires_at'=>now()->subMinute()]);DB::table('realtime_outbox')->delete();$live=app(Invalidations::class);$this->assertSame(1,$live->expireHolds());$this->assertSame(0,$live->expireHolds());$this->assertSame('hold',$b->fresh()->status);$b->update(['expires_at'=>now()->addMinutes(5)]);$this->travel(6)->minutes();$this->assertSame(1,$live->expireHolds());}
 public function test_failed_broadcast_is_retained_and_does_not_change_booking():void{$v=$this->venue();$b=$this->booking($v);Broadcast::shouldReceive('connection')->with('reverb')->andThrow(new \RuntimeException('Offline'));$this->assertSame(0,app(Invalidations::class)->flush());$this->assertGreaterThan(0,DB::table('realtime_outbox')->where('status','pending')->count());$this->assertSame('hold',$b->fresh()->status);}
 public function test_worker_publishes_only_safe_invalidations_and_removes_sent_rows():void{$this->venue();$broadcaster=\Mockery::mock();$broadcaster->shouldReceive('broadcast')->once()->with(\Mockery::type('array'),'platform.changed',\Mockery::on(fn($payload)=>array_keys($payload)===['kind','version']))->andReturnNull();Broadcast::shouldReceive('connection')->with('reverb')->andReturn($broadcaster);$this->assertSame(1,app(Invalidations::class)->flush());$this->assertSame(0,DB::table('realtime_outbox')->count());}
 public function test_csp_allows_websocket_only_for_current_portal_origin():void{$r=$this->get('https://reservas.example.com/');$this->assertStringContainsString("connect-src 'self' wss://reservas.example.com ",$r->headers->get('Content-Security-Policy'));$this->assertStringNotContainsString('wss://*',$r->headers->get('Content-Security-Policy'));}
 public function test_disabled_websockets_do_not_authorize_channels():void{config(['realtime.enabled'=>false]);$this->getJson('/api/me')->assertJsonPath('realtime.enabled',false);$this->postJson('/api/realtime/auth',['socket_id'=>'123.456','channel_name'=>'private-owner.1'])->assertStatus(503);}

}
